"const axios = require('axios');

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function test() {
  try {
    const url = 'https://bizno.net';
    console.log('1. First Request to get queue ticket...');

    const res1 = await axios.get(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
      }
    });

    console.log('Status:', res1.status);
    const cookies = res1.headers['set-cookie'] || [];
    console.log('Received Cookies:', cookies);

    // Extract cookie strings
    const cookieHeader = cookies.map(c => c.split(';')[0]).join('; ');
    console.log('Formatted Cookie Header:', cookieHeader);

    if (res1.data.includes('접속대기중')) {
      console.log('Result: Waiting queue detected! Sleeping for 11 seconds to bypass queue...');
      await sleep(11000);

      console.log('2. Second Request with Cookies...');
      const res2 = await axios.get(url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
          'Cookie': cookieHeader
        }
      });

      console.log('Status:', res2.status);
      const isQueueAgain = res2.data.includes('접속대기중');
      if (isQueueAgain) {
        console.log('Result: Failed. Still in waiting queue.');
      } else {
        console.log('Result: SUCCESS! Bypassed queue and reached bizno.net page!');
        // Print title of the target page if possible
        const titleMatch = res2.data.match(/<title>([^<]+)<\/title>/i);
        if (titleMatch) {
          console.log('Page Title:', titleMatch[1]);
        }
      }
    } else {
      console.log('Result: Success directly, no waiting queue active.');
    }
  } catch (err) {
    console.error('Error:', err.message);
  }
}

test();
"

